int fpm_stdio_init_main() /* {{{ */

{

	int fd = open("/dev/null", O_RDWR);



	if (0 > fd) {

		zlog(ZLOG_SYSERROR, "failed to init stdio: open(\"/dev/null\")");

		return -1;

	}



	if (0 > dup2(fd, STDIN_FILENO) || 0 > dup2(fd, STDOUT_FILENO)) {

		zlog(ZLOG_SYSERROR, "failed to init stdio: dup2()");

		close(fd);

		return -1;

	}

	close(fd);

	return 0;

}

